import React from 'react';
import { EMOTION_NAMES, QuestionResponse, RISK_LEVEL_NAMES } from '../types';

interface StudentStatusBarProps {
  consultCount: number;
  latestReport: {
    emotion?: QuestionResponse['emotion'];
    risk?: QuestionResponse['risk'];
    statModel?: QuestionResponse['statModel'];
  } | null;
  portraitPending?: boolean;
  reportPending?: boolean;
  onRefreshInsights?: () => void;
  refreshing?: boolean;
}

export const StudentStatusBar: React.FC<StudentStatusBarProps> = ({
  consultCount,
  latestReport,
  portraitPending,
  reportPending,
  onRefreshInsights,
  refreshing
}) => {
  const emotionKey = latestReport?.emotion?.emotion;
  const emotionLabel = emotionKey ? EMOTION_NAMES[emotionKey] || emotionKey : null;
  const risk = latestReport?.risk?.level;
  const riskLabel = risk ? RISK_LEVEL_NAMES[risk] || risk : null;
  const sessions = latestReport?.statModel?.totalSessions ?? consultCount;

  return (
    <div className="student-status-bar" role="status" aria-label="本次咨询概况">
      <div className="student-status-metrics">
        <span className="student-status-chip" title="累计有效咨询次数">
          <strong>{sessions}</strong> 次咨询
        </span>
        {emotionLabel && (
          <span className="student-status-chip" title="最近一次咨询识别的主要情绪">
            情绪 <strong>{emotionLabel}</strong>
          </span>
        )}
        {riskLabel && (
          <span className={`student-status-chip risk-${risk}`} title="系统评估的风险等级，仅供参考">
            风险 <strong>{riskLabel}</strong>
          </span>
        )}
        {reportPending && (
          <button
            type="button"
            className="student-status-chip portrait-pending student-status-chip-btn"
            onClick={onRefreshInsights}
            disabled={refreshing}
            title="点击刷新报告状态"
          >
            详细报告生成中…
          </button>
        )}
        {portraitPending && (
          <button
            type="button"
            className="student-status-chip portrait-pending student-status-chip-btn"
            onClick={onRefreshInsights}
            disabled={refreshing}
            title="点击刷新画像状态"
          >
            咨询画像生成中…
          </button>
        )}
      </div>
      {onRefreshInsights && (
        <button
          type="button"
          className="student-status-refresh"
          onClick={onRefreshInsights}
          disabled={refreshing}
        >
          {refreshing ? '刷新中…' : '刷新报告与趋势'}
        </button>
      )}
    </div>
  );
};
